{
  "my-guard": {
    "PreToolUse": [
      {
        "matcher": "*",
        "hooks": [
          {
            "type": "command",
            "command": "./guard.sh"
          }
        ]
      }
    ]
  },
  "claude-mem": {
    "Notification": [
      {
        "type": "command",
        "command": "./keep.sh"
      }
    ],
    "SessionStart": [
      {
        "type": "command",
        "command": "<SANDBOX>/home/.bun/bin/bun <SANDBOX>/home/.claude/plugins/marketplaces/thedotmack/plugin/scripts/worker-service.cjs hook antigravity-cli context",
        "timeout": 30
      }
    ],
    "PreToolUse": [
      {
        "matcher": "*",
        "hooks": [
          {
            "type": "command",
            "command": "<SANDBOX>/home/.bun/bin/bun <SANDBOX>/home/.claude/plugins/marketplaces/thedotmack/plugin/scripts/worker-service.cjs hook antigravity-cli observation",
            "timeout": 30
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "*",
        "hooks": [
          {
            "type": "command",
            "command": "<SANDBOX>/home/.bun/bin/bun <SANDBOX>/home/.claude/plugins/marketplaces/thedotmack/plugin/scripts/worker-service.cjs hook antigravity-cli observation",
            "timeout": 30
          }
        ]
      }
    ],
    "PostInvocation": [
      {
        "type": "command",
        "command": "<SANDBOX>/home/.bun/bin/bun <SANDBOX>/home/.claude/plugins/marketplaces/thedotmack/plugin/scripts/worker-service.cjs hook antigravity-cli observation",
        "timeout": 30
      }
    ],
    "Stop": [
      {
        "type": "command",
        "command": "<SANDBOX>/home/.bun/bin/bun <SANDBOX>/home/.claude/plugins/marketplaces/thedotmack/plugin/scripts/worker-service.cjs hook antigravity-cli summarize",
        "timeout": 30
      }
    ]
  },
  "SessionStart": [
    {
      "matcher": "*",
      "hooks": [
        {
          "name": "other",
          "type": "command",
          "command": "./other.sh"
        }
      ]
    }
  ]
}
